from flask import Flask, jsonify, request
from datetime import datetime
import threading

app = Flask(__name__)
lock = threading.Lock()

state = {
    'users': {
        'admin': {'password': 'admin', 'roles': ['administrator']},
        'teacher': {'password': 'teacher', 'roles': ['teacher']},
        'office': {'password': 'office', 'roles': ['front-desk', 'billing']},
    },
    'sessions': {},
    'families': {},
    'children': {},
    'invoices': {},
    'imports': {},
    'audit': [],
    'counters': {'family': 1, 'child': 1, 'invoice': 1, 'import': 1},
    'record_locks': {},
}


def now():
    return datetime.utcnow().isoformat() + 'Z'


def log(action, user, target, details=None):
    state['audit'].append({'time': now(), 'action': action, 'user': user, 'target': target, 'details': details or {}})


def session_user():
    token = request.headers.get('X-Session-Token')
    if not token or token not in state['sessions']:
        return None
    return state['sessions'][token]


def require_role(*roles):
    user = session_user()
    if not user:
        return None, (jsonify({'error': 'authentication required'}), 401)
    if not set(user['roles']).intersection(roles):
        return None, (jsonify({'error': 'forbidden'}), 403)
    return user, None


def next_id(kind):
    val = state['counters'][kind]
    state['counters'][kind] += 1
    return str(val)


@app.post('/login')
def login():
    data = request.get_json(force=True)
    user = state['users'].get(data.get('username'))
    if not user or user['password'] != data.get('password'):
        return jsonify({'error': 'invalid credentials'}), 401
    token = f"t{len(state['sessions'])+1}"
    state['sessions'][token] = {'username': data['username'], 'roles': user['roles']}
    log('login', data['username'], 'session')
    return jsonify({'token': token, 'roles': user['roles']})


@app.post('/families')
def create_family():
    user, err = require_role('administrator', 'front-desk', 'billing')
    if err: return err
    data = request.get_json(force=True)
    fid = next_id('family')
    state['families'][fid] = {'id': fid, 'name': data.get('name'), 'contact': data.get('contact', {}), 'archived': False, 'children': []}
    log('create_family', user['username'], f'family:{fid}')
    return jsonify(state['families'][fid]), 201


@app.post('/children')
def create_child():
    user, err = require_role('administrator', 'front-desk')
    if err: return err
    data = request.get_json(force=True)
    cid = next_id('child')
    state['children'][cid] = {'id': cid, 'family_id': data.get('family_id'), 'name': data.get('name'), 'allergies': data.get('allergies', []), 'immunizations': data.get('immunizations', []), 'status': 'active', 'draft': False, 'updated_at': now()}
    if data.get('family_id') in state['families']:
        state['families'][data.get('family_id')]['children'].append(cid)
    log('create_child', user['username'], f'child:{cid}')
    return jsonify(state['children'][cid]), 201


@app.post('/children/<cid>/archive')
def archive_child(cid):
    user, err = require_role('administrator')
    if err: return err
    child = state['children'].get(cid)
    if not child:
        return jsonify({'error': 'not found'}), 404
    child['status'] = 'archived'
    child['archived_at'] = now()
    log('archive_child', user['username'], f'child:{cid}')
    return jsonify(child)


@app.post('/invoices')
def create_invoice():
    user, err = require_role('administrator', 'billing', 'front-desk')
    if err: return err
    data = request.get_json(force=True)
    iid = next_id('invoice')
    state['invoices'][iid] = {'id': iid, 'family_id': data.get('family_id'), 'amount': float(data.get('amount', 0)), 'paid_amount': 0.0, 'status': 'draft' if data.get('draft', True) else 'submitted', 'payments': [], 'updated_at': now()}
    log('create_invoice', user['username'], f'invoice:{iid}')
    return jsonify(state['invoices'][iid]), 201


@app.post('/invoices/<iid>/submit')
def submit_invoice(iid):
    user, err = require_role('administrator', 'billing')
    if err: return err
    inv = state['invoices'].get(iid)
    if not inv:
        return jsonify({'error': 'not found'}), 404
    inv['status'] = 'submitted'
    inv['updated_at'] = now()
    log('submit_invoice', user['username'], f'invoice:{iid}')
    return jsonify(inv)


@app.post('/invoices/<iid>/pay')
def pay_invoice(iid):
    user, err = require_role('administrator', 'billing')
    if err: return err
    inv = state['invoices'].get(iid)
    if not inv:
        return jsonify({'error': 'not found'}), 404
    data = request.get_json(force=True)
    amt = float(data.get('amount', 0))
    inv['paid_amount'] += amt
    inv['payments'].append({'date': now(), 'amount': amt, 'type': 'payment'})
    if inv['paid_amount'] <= 0:
        inv['status'] = 'unpaid'
    elif inv['paid_amount'] < inv['amount']:
        inv['status'] = 'partial'
    else:
        inv['status'] = 'paid'
    inv['updated_at'] = now()
    log('pay_invoice', user['username'], f'invoice:{iid}', {'amount': amt})
    return jsonify(inv)


@app.get('/records/<kind>/<rid>')
def get_record(kind, rid):
    user = session_user()
    if not user:
        return jsonify({'error': 'authentication required'}), 401
    if kind == 'family': rec = state['families'].get(rid)
    elif kind == 'child': rec = state['children'].get(rid)
    elif kind == 'invoice': rec = state['invoices'].get(rid)
    else: return jsonify({'error': 'bad kind'}), 400
    if not rec:
        return jsonify({'error': 'not found'}), 404
    lock_owner = state['record_locks'].get(f'{kind}:{rid}')
    if lock_owner and lock_owner != user['username']:
        return jsonify({'record': rec, 'warning': f'being edited by {lock_owner}', 'read_only': True})
    state['record_locks'][f'{kind}:{rid}'] = user['username']
    log('view_record', user['username'], f'{kind}:{rid}')
    return jsonify(rec)


@app.post('/imports/preview')
def import_preview():
    user, err = require_role('administrator')
    if err: return err
    data = request.get_json(force=True)
    iid = next_id('import')
    records = data.get('records', [])
    flagged = [r for r in records if any(v in (None, '', 'UNKNOWN') for v in r.values())]
    state['imports'][iid] = {'id': iid, 'records': records, 'flagged': flagged, 'status': 'preview'}
    log('import_preview', user['username'], f'import:{iid}')
    return jsonify(state['imports'][iid])


@app.post('/imports/<iid>/finalize')
def import_finalize(iid):
    user, err = require_role('administrator')
    if err: return err
    imp = state['imports'].get(iid)
    if not imp:
        return jsonify({'error': 'not found'}), 404
    imp['status'] = 'finalized'
    log('import_finalize', user['username'], f'import:{iid}')
    return jsonify(imp)


@app.get('/audit')
def audit():
    user, err = require_role('administrator')
    if err: return err
    return jsonify(state['audit'])


@app.get('/')
def index():
    return jsonify({'service': 'Nenios Child Care Management', 'status': 'running'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000)
EOF

