import app


def login(client, username, password):
    return client.post('/login', json={'username': username, 'password': password}).get_json()['token']


def test_family_invoice_flow():
    client = app.app.test_client()
    t = login(client, 'admin', 'admin')
    headers = {'X-Session-Token': t}
    fam = client.post('/families', json={'name': 'Smith'}, headers=headers).get_json()
    child = client.post('/children', json={'family_id': fam['id'], 'name': 'Ava'}, headers=headers).get_json()
    assert child['family_id'] == fam['id']
    inv = client.post('/invoices', json={'family_id': fam['id'], 'amount': 100, 'draft': True}, headers=headers).get_json()
    assert inv['status'] == 'draft'
    inv = client.post(f"/invoices/{inv['id']}/submit", headers=headers).get_json()
    assert inv['status'] == 'submitted'
    inv = client.post(f"/invoices/{inv['id']}/pay", json={'amount': 40}, headers=headers).get_json()
    assert inv['status'] == 'partial'
    inv = client.post(f"/invoices/{inv['id']}/pay", json={'amount': 60}, headers=headers).get_json()
    assert inv['status'] == 'paid'


def test_concurrent_read_only_warning():
    client = app.app.test_client()
    admin = login(client, 'admin', 'admin')
    office = login(client, 'office', 'office')
    fam = client.post('/families', json={'name': 'Jones'}, headers={'X-Session-Token': admin}).get_json()
    first = client.get(f"/records/family/{fam['id']}", headers={'X-Session-Token': admin}).get_json()
    second = client.get(f"/records/family/{fam['id']}", headers={'X-Session-Token': office}).get_json()
    assert 'warning' in second
    assert first['name'] == 'Jones'


def test_import_preview_flags_unknowns():
    client = app.app.test_client()
    t = login(client, 'admin', 'admin')
    resp = client.post('/imports/preview', json={'records': [{'name': 'x'}, {'name': '', 'age': 4}]}, headers={'X-Session-Token': t}).get_json()
    assert len(resp['flagged']) == 1
EOF

